static inline bool __c3_type_matches(c3typeid_t self_type, c3typeid_t target_type) {
	if (!self_type || !target_type) { return false; }
	for (c3typeid_t t = self_type; t != NULL; t = t->parentof) {
		if (t == target_type) { return true; }
	}
	return false;
}

